 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'
import { getTeamEmoji } from '../services/footballApi'

export default function Community() {
    const { user, profile } = useAuth()
    const [communities, setCommunities] = useState([])
    const [myCommunities, setMyCommunities] = useState([])
    const [publicPredictions, setPublicPredictions] = useState([])
    const [loading, setLoading] = useState(true)
    const [tab, setTab] = useState('feed') // feed, my, discover

    useEffect(() => {
        loadData()
    }, [tab, user])

    const loadData = async () => {
        setLoading(true)
        try {
            // Load public predictions
            const { data: predictions } = await supabase
                .from('public_predictions')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, points)
                `)
                .order('created_at', { ascending: false })
                .limit(20)

            setPublicPredictions(predictions || [])

            // Load all communities
            const { data: allCommunities } = await supabase
                .from('communities')
                .select(`
                    *,
                    profiles:creator_id (id, username, full_name, avatar_url)
                `)
                .order('member_count', { ascending: false })

            setCommunities(allCommunities || [])

            // Load communities user is a member of
            if (user) {
                const { data: memberCommunities } = await supabase
                    .from('community_members')
                    .select(`
                        community_id,
                        communities (*)
                    `)
                    .eq('user_id', user.id)
                    .eq('status', 'active')

                const myCommunityData = memberCommunities?.map(m => m.communities) || []
                setMyCommunities(myCommunityData)
            }

        } catch (error) {
            console.error('Error loading community data:', error)
        } finally {
            setLoading(false)
        }
    }

    const handleLike = async (predictionId) => {
        if (!user) {
            alert('Please sign in to like predictions')
            return
        }

        try {
            // Check if already liked
            const { data: existing } = await supabase
                .from('public_prediction_likes')
                .select('*')
                .eq('prediction_id', predictionId)
                .eq('user_id', user.id)
                .single()

            if (existing) {
                // Unlike
                await supabase
                    .from('public_prediction_likes')
                    .delete()
                    .eq('prediction_id', predictionId)
                    .eq('user_id', user.id)

                await supabase
                    .from('public_predictions')
                    .update({ likes_count: supabase.rpc('decrement', { x: 1 }) })
                    .eq('id', predictionId)
            } else {
                // Like
                await supabase
                    .from('public_prediction_likes')
                    .insert({ prediction_id: predictionId, user_id: user.id })

                await supabase
                    .from('public_predictions')
                    .update({ likes_count: supabase.rpc('increment', { x: 1 }) })
                    .eq('id', predictionId)
            }

            // Refresh data
            loadData()
        } catch (error) {
            console.error('Error liking prediction:', error)
        }
    }

    const renderPrediction = (pred) => {
        const isLiked = false // We'll implement this properly
        const data = pred.prediction_data || {}
        
        let resultEmoji = '🤝'
        if (data.result === 'Home Win') resultEmoji = '🏠'
        else if (data.result === 'Away Win') resultEmoji = '✈️'

        return (
            <div key={pred.id} className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition">
                <div className="flex items-center gap-3 mb-3">
                    <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                        {pred.profiles?.username?.[0]?.toUpperCase() || 'U'}
                    </div>
                    <div>
                        <div className="font-semibold">{pred.profiles?.full_name || pred.profiles?.username || 'Unknown'}</div>
                        <div className="text-sm text-gray-500">@{pred.profiles?.username || 'user'}</div>
                    </div>
                </div>

                <div className="bg-gray-50 rounded-lg p-3 mb-3">
                    <div className="flex items-center justify-between">
                        <span className="text-lg">{resultEmoji}</span>
                        <span className="font-bold">{data.result || 'Draw'}</span>
                        <span className="text-sm text-gray-500">🟨{data.yellowCards || 0} 🟥{data.redCards || 0}</span>
                        <span className="text-sm text-gray-500">🏁{data.corners || 0}</span>
                    </div>
                </div>

                <div className="flex items-center justify-between text-sm">
                    <button 
                        onClick={() => handleLike(pred.id)}
                        className={`flex items-center gap-1 ${isLiked ? 'text-red-500' : 'text-gray-400 hover:text-red-500'} transition`}
                    >
                        ❤️ {pred.likes_count || 0}
                    </button>
                    <span className="text-gray-400">{new Date(pred.created_at).toLocaleDateString()}</span>
                </div>
            </div>
        )
    }

    const renderCommunityCard = (community) => {
        const isMember = myCommunities.some(c => c.id === community.id)
        const isCreator = user?.id === community.creator_id

        return (
            <Link 
                to={`/community/${community.id}`} 
                key={community.id}
                className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition block"
            >
                <div className="flex items-start justify-between">
                    <div className="flex-1">
                        <div className="flex items-center gap-2">
                            <span className="text-2xl">🏛️</span>
                            <h3 className="font-bold text-gray-800">{community.name}</h3>
                        </div>
                        <p className="text-sm text-gray-500 mt-1 line-clamp-2">
                            {community.description || 'A private community for football predictions'}
                        </p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R50/month</span>
                        </div>
                    </div>
                    <div className="ml-4">
                        {isCreator ? (
                            <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>
                        ) : isMember ? (
                            <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">Member</span>
                        ) : (
                            <span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full">Join</span>
                        )}
                    </div>
                </div>
            </Link>
        )
    }

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">👥 Community</h1>
                    <p className="text-gray-500">Share predictions, join communities, and connect with fans</p>
                </div>
                <Link 
                    to="/community/create"
                    className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium"
                >
                    + Create Community
                </Link>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-6">
                <button
                    onClick={() => setTab('feed')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        tab === 'feed' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    📰 Feed
                </button>
                <button
                    onClick={() => setTab('my')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        tab === 'my' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    📁 My Communities
                </button>
                <button
                    onClick={() => setTab('discover')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        tab === 'discover' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    🔍 Discover
                </button>
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading...</div>
                </div>
            ) : (
                <>
                    {/* Feed Tab */}
                    {tab === 'feed' && (
                        <div>
                            {publicPredictions.length === 0 ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">📊</div>
                                    <p className="text-gray-500">No public predictions yet</p>
                                    <p className="text-sm text-gray-400">Be the first to share your prediction!</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {publicPredictions.map(renderPrediction)}
                                </div>
                            )}
                        </div>
                    )}

                    {/* My Communities Tab */}
                    {tab === 'my' && (
                        <div>
                            {!user ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🔒</div>
                                    <p className="text-gray-500">Please sign in to see your communities</p>
                                </div>
                            ) : myCommunities.length === 0 ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🏛️</div>
                                    <p className="text-gray-500">You haven't joined any communities yet</p>
                                    <p className="text-sm text-gray-400">Discover communities and start predicting with friends</p>
                                    <button 
                                        onClick={() => setTab('discover')}
                                        className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                                    >
                                        Discover Communities
                                    </button>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {myCommunities.map(renderCommunityCard)}
                                </div>
                            )}
                        </div>
                    )}

                    {/* Discover Tab */}
                    {tab === 'discover' && (
                        <div>
                            {communities.length === 0 ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🔍</div>
                                    <p className="text-gray-500">No communities found</p>
                                    <p className="text-sm text-gray-400">Be the first to create a community!</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {communities.map(renderCommunityCard)}
                                </div>
                            )}
                        </div>
                    )}
                </>
            )}
        </div>
    )
}
